\text{EquityNeeded} 
= \frac{\text{CallAmount}}{\text{PotBeforeCall} + \text{CallAmount} + \text{VillainRiskedThisStreet}}

\text{In standard heads-up pots where Villain has already bet or shoved and you face that bet, }\text{VillainRiskedThisStreet} = 0,\text{ so}

\text{EquityNeeded} = \frac{C}{P + C}

\text{PotOdds (ratio)} = \frac{P}{C}
\quad\Rightarrow\quad
\text{EquityNeeded} = \frac{1}{\text{PotOdds} + 1}

\text{RIO} 
= \frac{\mathbb{E}[L_{\text{future}}]}{C}
\\[6pt]
\text{where }\mathbb{E}[L_{\text{future}}] 
= p_{\text{behind}}\,L_{\text{behind}} + p_{\text{caught}}\,L_{\text{caught}} + p_{\text{bluffed}}\,L_{\text{bluffed}}
\\[10pt]
\text{Effective Pot Odds} 
= \frac{P + C}{C + \mathbb{E}[L_{\text{future}}]}

\text{Equity} \approx \begin{cases}
\min\bigl(1,\;4 \cdot N\%\bigr), & \text{two cards to come (Rule of 4)} \\
\min\bigl(1,\;2 \cdot N\%\bigr), & \text{one card to come (Rule of 2)}
\end{cases}

\\[6pt]
\text{More formally, as a decimal probability:}\\[4pt]
E_{2}(N) \approx \min\left(1,\;0.04\,N\right)\\[2pt]
E_{1}(N) \approx \min\left(1,\;0.02\,N\right)

\\[6pt]
\text{where }E_{2}(N)\text{ is equity with two cards to come, and }E_{1}(N)\text{ with one card to come.}
